import React, { useState, useEffect } from "react";
import styled from "styled-components";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import LorryImage from "../assets/images/TN34K3749.jpeg";

const HomePage = () => {
  const STATIC_NAME = "Thangavelu";
  const STATIC_PHONE = "9443769338";

  const [lorries, setLorries] = useState([]);
  const [isFormVisible, setIsFormVisible] = useState(false);
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [ownerPhone, setOwnerPhone] = useState("");
  const [model, setModel] = useState("");
  const [yearBuilt, setYearBuilt] = useState("");
  const [ownerName, setOwnerName] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const fetchLorries = async () => {
      try {
        const response = await axios.get("http://localhost:5001/api/lorry");
        setLorries(response.data);
        console.log("Lorries fetched:", response.data);
      } catch (error) {
        console.error("Error fetching lorries:", error);
      }
    };
    fetchLorries();
  }, []);

  const handleAddLorry = () => {
    setIsFormVisible(!isFormVisible);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const newLorry = {
        registration_number: registrationNumber,
        owner_phone: ownerPhone, // Ensure phone is passed to match the owner
        model,
        year_built: yearBuilt,
        owner_name: ownerName,
      };
      await axios.post("http://localhost:5001/api/lorry/add", newLorry);
      alert("Lorry added successfully");
      setIsFormVisible(false);
      const response = await axios.get("http://localhost:5001/api/lorry");
      setLorries(response.data);
    } catch (error) {
      console.error("Error adding lorry:", error);
      alert("Failed to add lorry");
    }
  };

  const handleDeleteLorry = async (id) => {
    try {
      await axios.delete(`http://localhost:5001/api/lorry/${id}`);
      alert("Lorry deleted successfully");
      setLorries(lorries.filter((lorry) => lorry.id !== id));
    } catch (error) {
      console.error("Error deleting lorry:", error);
      alert("Failed to delete lorry");
    }
  };

  const handleLorryClick = (id) => {
    console.log("Navigating to dashboard with ID:", id);
    navigate(`/dashboard/${id}`);
  };

  const handleLogout = () => {
    localStorage.removeItem("authToken");
    navigate("/login");
  };

  return (
    <Container>
      <Header>
        <CompanyName>Sri Murugan Rig Service</CompanyName>
        <OwnerInfo>
          <OwnerName>{STATIC_NAME}</OwnerName>
          <OwnerPhone>{STATIC_PHONE}</OwnerPhone>
        </OwnerInfo>
        <LogoutButton onClick={handleLogout}>Logout</LogoutButton>
      </Header>

      <AddLorryButton onClick={handleAddLorry}>
        {isFormVisible ? "Cancel" : "Add Lorry"}
      </AddLorryButton>

      {isFormVisible && (
        <AddLorryForm onSubmit={handleSubmit}>
          <Input
            type="text"
            placeholder="Registration Number"
            value={registrationNumber}
            onChange={(e) => setRegistrationNumber(e.target.value)}
            required
          />
          <Input
            type="text"
            placeholder="Owner Name"
            value={ownerName}
            onChange={(e) => setOwnerName(e.target.value)}
            required
          />
          <Input
            type="text"
            placeholder="Owner Phone"
            value={ownerPhone}
            onChange={(e) => setOwnerPhone(e.target.value)}
            required
          />
          <Input
            type="text"
            placeholder="Model"
            value={model}
            onChange={(e) => setModel(e.target.value)}
            required
          />
          <Input
            type="number"
            placeholder="Year Built"
            value={yearBuilt}
            onChange={(e) => setYearBuilt(e.target.value)}
            required
          />
          <SubmitButton type="submit">Add Lorry</SubmitButton>
        </AddLorryForm>
      )}

      <LorryListContainer>
        {lorries.map((lorry) => (
          <LorryCard key={lorry.registration_number} onClick={() => handleLorryClick(lorry.id)}>
            <OwnerPhoneText>{lorry.owner_phone || "Unknown Owner"}</OwnerPhoneText>

            <ImageContainer>
              <img src={LorryImage} alt="Lorry model TN34K3749" />
            </ImageContainer>

            <LorryDetails>
              <div>Owner Name: {lorry.owner_name}</div>
              <div>Registration: {lorry.registration_number}</div>
              <div>Model: {lorry.model}</div>
              <div>Year Built: {lorry.year_built}</div>
            </LorryDetails>

            <DeleteButton
              onClick={(e) => {
                e.stopPropagation();
                handleDeleteLorry(lorry.registration_number);
              }}
            >
              Delete
            </DeleteButton>
          </LorryCard>
        ))}
      </LorryListContainer>
    </Container>
  );
};

// Styled Components

const Container = styled.div`
  padding: 20px;
`;

const Header = styled.header`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
`;

const CompanyName = styled.h1`
  font-size: 24px;
`;

const OwnerInfo = styled.div`
  text-align: right;
`;

const OwnerName = styled.div`
  font-weight: bold;
`;

const OwnerPhone = styled.div``;

const LogoutButton = styled.button`
  padding: 8px 15px;
  background-color: #f44336;
  color: white;
  border: none;
  cursor: pointer;
  border-radius: 5px;
`;

const AddLorryButton = styled.button`
  padding: 10px 20px;
  background-color: #4caf50;
  color: white;
  border: none;
  cursor: pointer;
  border-radius: 5px;
  margin-top: 20px;
`;

const AddLorryForm = styled.form`
  margin-top: 20px;
`;

const Input = styled.input`
  display: block;
  margin-bottom: 10px;
  padding: 10px;
  width: 100%;
  border-radius: 5px;
  border: 1px solid #ccc;
`;

const SubmitButton = styled.button`
  padding: 10px 20px;
  background-color: #4caf50;
  color: white;
  border: none;
  cursor: pointer;
  border-radius: 5px;
`;

const LorryListContainer = styled.div`
  margin-top: 20px;
`;

const LorryCard = styled.div`
  display: flex;
  align-items: center;
  border: 1px solid #ccc;
  padding: 15px;
  margin-bottom: 15px;
  cursor: pointer;
`;

const OwnerPhoneText = styled.div`
  font-size: 14px;
  color: gray;
`;

const ImageContainer = styled.div`
  width: 100px;
  height: 80px;
  margin-right: 20px;
`;

const LorryDetails = styled.div`
  flex: 1;
`;

const DeleteButton = styled.button`
  background-color: #f44336;
  color: white;
  padding: 5px 10px;
  border: none;
  cursor: pointer;
  border-radius: 5px;
  margin-left: 15px;
`;

export default HomePage;
